-- Paket 13.11.2026: cart quantity buttons (chunk 17) + mobile filters (new chunk, template 18). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- CHECK. Changes nothing. Before: 3 x OK. After: 3 x DONE. Any MISMATCH - stop.
SELECT itog, COUNT(*) AS n, GROUP_CONCAT(chto ORDER BY chto SEPARATOR '; ') AS what FROM (
SELECT _utf8mb4 0x312E20D0A7D0B0D0BDD0BA20D0BAD0BED180D0B7D0B8D0BDD18B2074706C2E6D73436172742028313729 AS chto, CASE WHEN c.id IS NULL THEN _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 WHEN c.snippet LIKE '%hts-qty-btn%' THEN _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E WHEN ROUND((CHAR_LENGTH(CONVERT(c.snippet USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(c.snippet USING utf8mb4), _utf8mb4 0x3C666F726D206D6574686F643D22706F73742220636C6173733D226D73325F666F726D22207374796C653D22646973706C61793A666C657821696D706F7274616E743B616C69676E2D6974656D733A63656E74657221696D706F7274616E743B6761703A36707821696D706F7274616E743B6D617267696E3A3021696D706F7274616E74223E, ''))) / 134) = 1 AND ROUND((CHAR_LENGTH(CONVERT(c.snippet USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(c.snippet USING utf8mb4), _utf8mb4 , ''))) / 254) = 1 AND ROUND((CHAR_LENGTH(CONVERT(c.snippet USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(c.snippet USING utf8mb4), _utf8mb4 0x2428646F63756D656E74292E72656164792866756E6374696F6E28297B20242822236D734361727420696E7075745B747970653D6E756D6265725D22292E7374657070657228293B207D293B, ''))) / 76) = 1 AND ROUND((CHAR_LENGTH(CONVERT(c.snippet USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(c.snippet USING utf8mb4), _utf8mb4 0x3C2F7374796C653E, ''))) / 8) = 1 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 END AS itog
FROM (SELECT 1 AS x) d LEFT JOIN modx_site_htmlsnippets c ON c.id = 17 AND c.name = 'tpl.msCart'
UNION ALL
SELECT _utf8mb4 0x322E20D0A8D0B0D0B1D0BBD0BED0BD20C2ABD09FD0BED0B4D0BAD0B0D182D0B5D0B3D0BED180D0B8D18FC2BB2028313829, CASE WHEN t.id IS NULL THEN _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 WHEN t.content LIKE '%[[$HtsMobileFilters]]%' THEN _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E WHEN ROUND((CHAR_LENGTH(CONVERT(t.content USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x5B5B24636F6E74656E7463617465676F72795D5D, ''))) / 20) = 1 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD09DD09520D0A1D09ED092D09FD090D094D090D095D0A220E2809420D181D182D0BED0BF2C20D181D0BAD180D0B8D0BDD188D0BED182 END
FROM (SELECT 1 AS x) d LEFT JOIN modx_site_templates t ON t.id = 18 AND t.templatename = _utf8mb4 0xD09FD0BED0B4D0BAD0B0D182D0B5D0B3D0BED180D0B8D18F
UNION ALL
SELECT _utf8mb4 0x332E20D09DD0BED0B2D18BD0B920D187D0B0D0BDD0BA204874734D6F62696C6546696C74657273, CASE WHEN (SELECT COUNT(*) FROM modx_site_htmlsnippets WHERE name = 'HtsMobileFilters') = 0 THEN _utf8mb4 0xD0A1D09ED092D09FD090D094D090D095D0A220E2809420D0BCD0BED0B6D0BDD0BE20D0BFD0B5D180D0B5D0BDD0BED181D0B8D182D18C ELSE _utf8mb4 0xD0A3D096D09520D09FD095D0A0D095D09DD095D0A1D095D09DD09E END
) q GROUP BY itog;
